import{z as A,x as p,o as t,c as d,q as o,j as s,D as E,d as l,s as i,S as n,b as e}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"EUV 对多重曝光的成本交叉","description":"","frontmatter":{"title":"EUV 对多重曝光的成本交叉","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/euv-vs-multipattern-cost-crossover.md","filePath":"litho/euv-vs-multipattern-cost-crossover.md","lastUpdated":1791063341000}'),B={name:"litho/euv-vs-multipattern-cost-crossover.md"};function c(m,a,V,h,u,D){const r=p("Mermaid");return t(),d("div",null,[a[2]||(a[2]=o('<h1 id="euv-对多重曝光的成本交叉" tabindex="-1">EUV 对多重曝光的成本交叉 <a class="header-anchor" href="#euv-对多重曝光的成本交叉" aria-label="Permalink to &quot;EUV 对多重曝光的成本交叉&quot;">​</a></h1><div class="epigraph"><p>交叉点是「一张 EUV 替换几次浸没 + 切线」在周期、套刻与掩模上的平衡，随剂量、pellicle 和层类型移动。</p><footer>—— 对照 ASML 与代工对 EUV 插入临界层、浸没保留次临界层的公开叙事</footer></div><p><a href="/litho/cost-per-layer-wafer">上一课</a>给出按层加总。缺口是决策：某层该不该从 LELE/SAQP 迁 EUV。本课钉成本交叉。<a href="/litho/duv-multipattern-cost">DUV 多重代价</a> 已写 7/5 nm 结构；这里收成交叉逻辑。机台本身多贵，留给<a href="/litho/tool-price-depreciation">下一课</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>EUV 单次买回二维与减张数、减同层套刻；付出源功率、随机剂量、掩模、pellicle。浸没多重买分辨率，付出步骤与设计规则。交叉点按层：密孔可能早迁，宽松金属可能永不迁。高 NA 再改一次交叉（半场、更贵机台、薄胶）。</p><p><span class="marginnote">初学者容易把交叉点当成全行业同一条线。它随层的节距、EUV 剂量、pellicle 透过率与该厂的随机水平移动：密孔层往往早迁，宽松金属可能永远留在浸没上。问「EUV 何时全面取代浸没」本身就问错了对象——对象是层。</span></p><p>缺口是<strong>移动的平衡</strong>，不是「EUV 总更贵」或「总更便宜」。不填美元交叉点。</p><h3 id="公开叙事可引用结构" tabindex="-1">公开叙事可引用结构 <a class="header-anchor" href="#公开叙事可引用结构" aria-label="Permalink to &quot;公开叙事可引用结构&quot;">​</a></h3><p>ASML 把浸没定位为多重与次临界工作马，NXE 为临界层。混跑与 cross-match 是交叉之后仍存在的状态，不是过渡年特写。</p><p><span class="marginnote">随机悬崖可以把「光学上该迁 EUV」的层留在多重，或迫使 EUV 双重。交叉含随机，不只含 wph。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>对候选层：列 DUV 模块步骤 vs EUV 模块步骤，加套刻风险、设计自由度、掩模周期。灵敏度扫剂量与pellicle T。决策是 DTCO，不是财务单独。</p><p><span class="marginnote">DTCO（设计–工艺协同优化）就是「设计和工艺一起改作业」：先看设计能不能放宽这条规则、少一次分解，再看工艺能不能补回性能，最后才轮到成本表拍板。迁层决策属于这一类，不是财务部单独算单价。</span></p>',13)),(t(),s(n,null,{default:E(()=>[i(r,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20L%5B%22%E5%80%99%E9%80%89%E5%B1%82%22%5D%20--%3E%20Q1%7B%22EUV%20%E5%8D%95%E6%AC%A1%E7%AA%97%E5%8F%A3%E5%A4%9F%E5%90%97%3F%22%7D%0A%20%20Q1%20--%3E%7C%E5%A4%9F%7C%20E1%5B%22%E8%BF%81%20EUV%20%E5%8D%95%E6%AC%A1%22%5D%0A%20%20Q1%20--%3E%7C%E4%B8%8D%E5%A4%9F%7C%20Q2%7B%22%E5%9B%BE%E5%BD%A2%E4%B8%80%E7%BB%B4%E8%BF%98%E6%98%AF%E4%BA%8C%E7%BB%B4%3F%22%7D%0A%20%20Q2%20--%3E%7C%E4%B8%80%E7%BB%B4%7C%20SP%5B%22spacer%20%E8%87%AA%E5%AF%B9%E5%87%86%20(SADP%2FSAQP)%22%5D%0A%20%20Q2%20--%3E%7C%E4%BA%8C%E7%BB%B4%7C%20Q3%7B%22%E6%B5%B8%E6%B2%A1%E5%A4%9A%E9%87%8D%20vs%20EUV%20%E5%8F%8C%E9%87%8D%22%7D%0A%20%20Q3%20--%3E%20CMP%5B%22%E6%AF%94%E6%AD%A5%E9%AA%A4%E6%95%B0%20%2F%20%E6%8E%A9%E6%A8%A1%20%2F%20%E5%A5%97%E5%88%BB%20%2F%20%E9%9A%8F%E6%9C%BA%22%5D%0A"})]),fallback:E(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=e("p",null,"这张图回答的是：拿到一个具体层，迁移决策怎么走——先问单次窗口，再问拓扑，最后才进成本比较。",-1)),a[4]||(a[4]=e("h2",{id:"机制",tabindex:"-1"},[l("机制 "),e("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),a[5]||(a[5]=e("p",null,"成本差 Δ ≈ (n_DUV · c_imm − c_EUV) + 掩模差 + 良率差。n_DUV 随节距涨；c_EUV 随剂量涨。交叉发生在 n 足够大且 c_EUV 被功率/pellicle 压下来时。这是结构式，系数来自当时厂数据，课文不编。",-1)),a[6]||(a[6]=e("p",null,[e("span",{class:"marginnote"},"给个纯结构性的例子感受比较方式：某层浸没方案要 3 次曝光、2 张额外掩模；迁 EUV 单次只要 1 次曝光、1 张掩模，但每次过机更贵、剂量更敏感。交叉问题就是「多次便宜的一共」什么时候贵过「一次贵的」——具体美元数各厂随时段变，结构不变。")],-1)),(t(),s(n,null,{default:E(()=>[i(r,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20N%5B%22%E5%88%86%E8%A7%A3%E6%AC%A1%E6%95%B0%22%5D%20--%3E%20DUV%5B%22%E6%B5%B8%E6%B2%A1%E6%A8%A1%E5%9D%97%E6%88%90%E6%9C%AC%22%5D%0A%20%20DOSE%5B%22EUV%20%E5%89%82%E9%87%8F%20%2F%20pellicle%22%5D%20--%3E%20EUV%5B%22EUV%20%E6%A8%A1%E5%9D%97%E6%88%90%E6%9C%AC%22%5D%0A%20%20DUV%20--%3E%20X%5B%22%E6%8C%89%E5%B1%82%E4%BA%A4%E5%8F%89%22%5D%0A%20%20EUV%20--%3E%20X%0A%20%20STO%5B%22%E9%9A%8F%E6%9C%BA%22%5D%20--%3E%20X%0A"})]),fallback:E(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[7]||(a[7]=o('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不预测某年全球交叉。不把所有层一次迁完。交叉不消除浸没机需求。</p><p>后课默认：层决策看交叉结构；下一课机台价格与折旧如何把 c_imm、c_EUV 变成会计数字。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>交叉按层，随分解次数、EUV 剂量与随机移动。</li><li>混跑是稳态；浸没仍服务次临界层。</li><li>只比较结构，不编美元交叉点。</li><li>出处：ASML/代工公开插入叙事；与多重代价课衔接。</li></ul>',5))])}const _=A(B,[["render",c]]);export{C as __pageData,_ as default};
